// Turned leg (lathe), base at y=0.
const TURN = [[0, 0], [0.8, 0], [0.92, 0.02], [0.78, 0.05], [0.6, 0.13], [0.55, 0.44], [0.82, 0.5], [0.6, 0.56], [0.8, 0.64], [0.92, 0.7], [0.92, 1], [0, 1]];
